        "dua_alimal_ghayb" to DuaText("غٲر مرئی علم", "اے اللہ، نٗچھنہٕ تہٕ وچھنہٕ والن ہنٛد علم، آسمان تہٕ زمینک خالق، رب تہٕ ہر چیزک حاکمیت! بہٕ چھس گواہن دوان ز تو٘ہ علاوٕ چھ نہٕ کانٛہہ دیوتا۔ بہٕ چھس تٗمس نش پننہ شرارتس نش، تہٕ شیتان تہٕ تمہ سٕنز شرکہ نش پناہ یژھان۔", "صبح، شام تہٕ سونٛنہٕ برٛونٛہہ-پیغمبر اسلام صلی اللہ علیہ وسلم ہاو یہ ابو بکرس (ر)۔", "پانس تہٕ شیتان کس شرٕیس نش بچاو۔"),
        "dua_fitratil_islam" to DuaText("اسلام کی فطراہ", "أس چھ اسلام کہ فطراہس پیٹھ صبحس داخل گومت، دیانتداری ہنٛدس لفظس پیٹھ، پننس پیغمبر محمد صلی اللہ علیہ وسلم سند مذہبس پیٹھ تہٕ پننس مٲلۍ ابراہیم (ع) سند وتہٕ پیٹھ، یس سید تہٕ مسلمان اوس، تہٕ اوس نہٕ مشرکین ہنٛد۔", "صبح چھ بجے۔", "پرٛؠتھ صبحس پنن عقیدٕ نوٚو کرن۔"),
        "dua_amsayna_fitrah" to DuaText("شام اسلام کی فرشتہ پر", "أس چھ شامس اسلام کس فطراہس پیٹھ، دیانتداری ہنٛدس لفظس پیٹھ، پننس پیغمبر محمد صلی اللہ علیہ وسلم سند مذہبس پیٹھ تہٕ پننس مٲلۍ ابراہیم (ع) سند وتہٕ پیٹھ داخل گومت، یس سید تہٕ مسلمان اوس، تہٕ اوس نہٕ مشرکین ہنٛد۔", "شامچہ شامچہ۔", "پرٛؠتھ شامس کر پنن عقیدٕ دوبارٕ قٲیم۔"),
        "dua_tahleel_10_fajr" to DuaText("فخر تہٕ مغرب پتہٕ دس تہلیل", "کٲنہہ تہ چھ نہٕ عبادت کرنک حق، سوائے اللہ کہ، بغٲر شریک۔ ام سنٛد چھ حکومت تہٕ ام سنٛد چھ تعریف۔ سہ چھ زندگی دیوان تہٕ موت چھ دیوان، تہٕ أمس چھ ہر چیزس پیٹھ طاقت۔", "فجر (تہٕ مگھرب) پتہٕ دہن لٹہ، بیٹھن یا بولن نش منتقل گژھنہٕ برونٹھ۔", "دہہ اصل اعمال، دہن گناہ چھ مٹٲمت، دہن درجہٕ بڑٲئمت تہٕ پورٕ دۄہ شیتان نش بچاو۔"),
        "dua_la_hawla_kanz" to DuaText("جنتک اکھ خزانہٕ", "اللہ ہس علاوٕ چھنہٕ کانٛہہ طاقت تہٕ کانٛہہ طاقت۔", "اکثر، ہر وقت۔", "یہ چھ جنتک خزانن منٛز اکھ۔"),
        "dua_four_beloved_words" to DuaText("ژور ساروی کھوتہٕ زیادہ پسند کردہ الفاظ", "جلال چھ اللہ، ساری تعریف چھ اللہ خٲطرٕ، سوائے اللہ کے کٲنٛسہ تہٕ عبادتک حق چھنہٕ، تہٕ اللہ چھ ساروی کھوتہٕ بوٚڑ۔", "تم الفاظ یم اللہ ہس ساروی کھوتہٕ زیادٕ پسند چھ۔", "یم چھ پیغمبر اسلام صلی اللہ علیہ وسلم سٕند خٲطرٕہ آفتاب کہ طلوع آفتاب کہ ہر چیز کھوتہٕ زیادٕہ عزیز۔"),
        "dua_two_light_words" to DuaText("زبانہ پیٹھ چھ زٕ لفظ روشن۔", "جلال آسہٕ اللہ تہٕ ساری تعریف آسہٕ أمہ سٕنٛز۔ جلال آسہٕ اللہ یس عظیم چھ۔", "زبان پیٹھ چھ روشنی، پیمانس پیٹھ چھ بھاری۔", "انتہائی رحم کنس چھ محبت کران، زبان پیٹھ چھ ہلکہٕ تہٕ پیمانس پیٹھ چھ بھاری۔ (البقرۃ الأخاری)"),
        "dua_ya_dhal_jalal" to DuaText("یا دھال جلالی وال اکرم", "اے عظمت تہٕ عزتک مالک!", "اتھ تھٲیو دعا منٛز-پیغمبر صلی اللہ علیہ وسلم سند ہدایت۔", "پیغمبر صلی اللہ علیہ وسلم ین ووٚن:'یا دل جلالی وال اکرم'تھٲٹھ تھٲٹھ۔"),
        "dua_sleep_wadatu_janbi" to DuaText("بہٕ چھس تہنٛد ناوٕ سۭتۍ لیٹتھ۔", "بہٕ چھس پننس ناوس پیٹھ، پننس ربس، پنن طرف تھوان تہٕ بہٕ چھ تہنز ناوس پیٹھ زندٕ گژھان۔ اگر تہۍ میٚون روح چھ نوان، تیلہٕ کٔرو اتھ پیٹھ رحم، تہٕ اگر تہۍ چھ اتھ آزاد کران، تیلہٕ کٔرو اتھ بچاو یتھکن تہۍ پنن نیک نوکانن بچاوان چھو۔", "بسترس پیٹھ ژول تہٕ لیٹ۔", "سونٛنہٕ برٛونٛہہ کٔرو پنن روح اللہ ہس تفویض۔"),
        "dua_sleep_khalaqta_nafsi" to DuaText("تو٘ن چھ میٲنۍ روح بناومت۔", "اے اللہ، تو٘ہہ چھ میٚون روح بناومٕژ تہٕ تو٘ہہ ہیکیو یہ۔ امیک موت تہٕ امیوک زندگی چھ تو٘ہہ سٕنز۔ اگر تو٘ہ یہ زیٖن رکھو، تو٘ہ بچاو، تہٕ اگر تو٘ہ یہ مراو، تو٘ہ کر معاف۔ اے اللہ، بہٕ چھس تٗہنز بھلائی گھران۔", "سونٛنہٕ برٛونٛہہ-ابن عمر (ر) سند بیان۔", "پیغمبر اسلام صلی اللہ علیہ وسلم ین دژ یہ وننٕچ ہدایت۔"),
        "dua_sleep_atamana" to DuaText("سونٛنہٕ برٛونٛہہ کریو شکر گزاری۔", "تمام تعریفیں چھ اللہ خٲطرٕ یم اسہ کھٲو، اسہ پیٛو، اسہ کافی تہٕ اسہ پناہ دژ۔ کۭتیہ چھ یمن نش نہٕ کٲفی چھ کینٛہہ یمن نش نہٕ یمن پناہ دنس تہٕ نہ چھ کٲفی۔", "ییٚلہ زن سہ بسترس پؠٹھ آسہ۔", "یہ ووٚنۍ پیغمبر اسلام صلی اللہ علیہ وسلم ین بسترس پؠٹھ۔"),
        "dua_sleep_rabbas_samawat" to DuaText("رب آسمان-پنن قرض ادا کرو۔", "اے اللہ، آسمان، زمین تہٕ طاقتور تختک رب، سٗند رب تہٕ ہر چیزک رب، بییہٕ تہٕ کھجورک پتھر چھ تقسیم کرن وول، تورا، انجل تہٕ فرقن ہنٛد انکشاف کرن وول۔ بہٕ چھس تۄہہ منٛز ہر تتھ چیزچ برٲئی نش پناہ یژھان یم توہہ تھیو۔ اے اللہ، توہہ چھ گوڑنک، تۄہہ برونٹھ کنہہ تہٕ چھنہٕ۔ توہہ چھ آخری، تۄہہ پتہٕ کنہہ تہٕ چھ نہٕ۔ توہہ چھ نہٕ ساروی کھوتہٕ واضح، تو٘ہہ پیٹھ کنہہ تہٕ چھ نہٕ۔ توہہ چھ چھپتھ، تو٘ہہ چھ نہٕ کینٛہہ تہٕ۔ اسہ خٲطرٕ کر سٗند قرض طے تہٕ اسہ غربت نش آزاد۔", "سونٛنہٕ برٛونٛہہ، دٕچھنۍ طرفہٕ لیٹتھ-ہیٚچھناو فاطمہ (ر) ہس۔", "قرضہٕ تہٕ مشکلن نش نجات خٲطرٕ اکھ دعا۔"),
        "dua_sleep_fear" to DuaText("خوف یا نؠبرٕگی۔", "بہٕ چھس اللہ سٕنٛدۍ مکمل الفاظن منٛز أمہ سٕنٛد غصے تہٕ سزا نش، أمہ سٕنٛدؠن نوکرین ہنٛد بؠلہٕ نش، شیعلن ہنٛدؠن بوزن سۭتۍ تہٕ تہنٛدس مےٚ ینہٕ سۭتۍ پناہ یژھان۔", "ییٚلہ سونٛنس منٛز خوف یا بے چین محسوس گژھان آسہ۔", "یہ کرنہٕ سۭتۍ چھنہٕ أمس کانٛہہ نقصان۔"),
        "dua_waking_afani" to DuaText("جاگنہٕ: تمہ کٕر میانہ روح بحال۔", "ساری تعریفیں چھ اللہ خٲطرٕ یم میٚون جسمچ تندرستی دژ، میٚون روحن دژ مےٚ واپس تہٕ دیت مےٚ تٔمس یاد کرنک اجازت۔", "جاگنہٕ پیٹھ۔", "اکہ نو صبحٕ خٲطرٕہ چھ شکریہ۔"),
        "dua_allahu_rabbi" to DuaText("اے اللہ، اے اللہ، یس رب چھ۔", "اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ، اے اللہ اے اللہ، اے اللہ، اے اللہ اے اللہ اے اللہ، اے اللہ اے اللہ اے اللہ اے، اے اللہ اے اللہ اے اللہ اے، اے اللہ اے اللہ اے اللہ اے اللہ اے اللہ اے اللہ", "غم یا تکلیفس منٛز-پیغمبر صلی اللہ علیہ وسلم چھ یہ اسما بنت امیس (ر) یس ہیچھناومت۔", "مصیبت کس وقتس منٛز تھٲیو توہید۔"),
